#define CHECK(n, expression) do { if (!(expression)) return 20 + (n); } while (0)

static int seen;
static void custom(int *value) { ++seen; *value -= 4; }
int main(void) {
    int basic[] = {1, 2, 3, 4, 5};
    transform_array(basic, 5, triple);
    CHECK(1, basic[0] == 3 && basic[1] == 6 && basic[2] == 9 && basic[3] == 12 && basic[4] == 15);
